namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    public int Id { get; set; }
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
    public DateTime SubmittedAt { get; set; }
    public string? Notes { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new Department { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new Department { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new Department { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new Course { Id = 1, DepartmentId = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", InstructorName = "Dr. Alice Johnson", InstructorBio = "PhD in Computer Science from MIT. 15 years of teaching experience in introductory programming.", IsFeatured = true },
            new Course { Id = 2, DepartmentId = 1, Code = "CS201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs. Analysis of algorithm complexity.", Credits = 4, Schedule = "Tue/Thu 10:30-11:45 AM", InstructorName = "Dr. Bob Smith", InstructorBio = "Former Google engineer with expertise in algorithm design and optimization.", IsFeatured = true },
            new Course { Id = 3, DepartmentId = 1, Code = "CS301", Title = "Database Systems", Description = "Introduction to relational databases, SQL, normalization, and transaction processing.", Credits = 3, Schedule = "Mon/Wed 2:00-3:15 PM", InstructorName = "Dr. Carol Williams", InstructorBio = "Database researcher with publications in distributed systems and query optimization.", IsFeatured = false },
            new Course { Id = 4, DepartmentId = 1, Code = "CS401", Title = "Software Engineering", Description = "Software development methodologies, design patterns, testing, and project management.", Credits = 3, Schedule = "Tue/Thu 1:00-2:15 PM", InstructorName = "Dr. Alice Johnson", InstructorBio = "PhD in Computer Science from MIT. 15 years of teaching experience in introductory programming.", IsFeatured = false },

            // Mathematics
            new Course { Id = 5, DepartmentId = 2, Code = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", InstructorName = "Dr. David Lee", InstructorBio = "Award-winning mathematics educator specializing in making calculus accessible to all students.", IsFeatured = true },
            new Course { Id = 6, DepartmentId = 2, Code = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 9:00-10:15 AM", InstructorName = "Dr. Emily Chen", InstructorBio = "Research mathematician focused on applied linear algebra and machine learning foundations.", IsFeatured = false },
            new Course { Id = 7, DepartmentId = 2, Code = "MATH301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00-11:50 AM", InstructorName = "Dr. David Lee", InstructorBio = "Award-winning mathematics educator specializing in making calculus accessible to all students.", IsFeatured = false },

            // Physics
            new Course { Id = 8, DepartmentId = 3, Code = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00-1:50 PM + Lab Thu 2:00-4:00 PM", InstructorName = "Dr. Frank Martinez", InstructorBio = "Experimental physicist with research in condensed matter physics and science education.", IsFeatured = true },
            new Course { Id = 9, DepartmentId = 3, Code = "PHYS201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM-12:15 PM + Lab Fri 2:00-4:00 PM", InstructorName = "Dr. Grace Kim", InstructorBio = "Theoretical physicist specializing in quantum electrodynamics and photonics.", IsFeatured = false },
            new Course { Id = 10, DepartmentId = 3, Code = "PHYS301", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Mon/Wed 3:30-4:45 PM", InstructorName = "Dr. Grace Kim", InstructorBio = "Theoretical physicist specializing in quantum electrodynamics and photonics.", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        request.Id = _enrollmentRequests.Count + 1;
        request.SubmittedAt = DateTime.Now;
        _enrollmentRequests.Add(request);
    }
}

