@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService
@rendermode InteractiveServer

<PageTitle>Courses</PageTitle>

<h1>Courses</h1>

<div class="row mb-3">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses..." @bind="searchText" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

<table class="table table-striped">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Department</th>
            <th>Credits</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in FilteredCourses)
        {
            var dept = CatalogService.GetDepartment(course.DepartmentId);
            <tr>
                <td>@course.Code</td>
                <td>@course.Title</td>
                <td>@dept?.Name</td>
                <td>@course.Credits</td>
                <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
            </tr>
        }
    </tbody>
</table>

@if (!FilteredCourses.Any())
{
    <p class="text-muted">No courses found matching your criteria.</p>
}

@code {
    private string searchText = string.Empty;
    private string selectedDepartmentId = string.Empty;

    private List<Course> FilteredCourses =>
        CatalogService.GetCourses(
            string.IsNullOrWhiteSpace(searchText) ? null : searchText,
            string.IsNullOrWhiteSpace(selectedDepartmentId) ? null : int.Parse(selectedDepartmentId));
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Detail")</PageTitle>

@if (course is null)
{
    <p>Course not found.</p>
}
else
{
    var dept = CatalogService.GetDepartment(course.DepartmentId);

    <h1>@course.Title</h1>
    <h4 class="text-muted">@course.Code</h4>

    <div class="card mb-4">
        <div class="card-body">
            <p><strong>Description:</strong> @course.Description</p>
            <p><strong>Department:</strong> @dept?.Name</p>
            <p><strong>Credits:</strong> @course.Credits</p>
            <p><strong>Schedule:</strong> @course.Schedule</p>
            <hr />
            <p><strong>Instructor:</strong> @course.InstructorName</p>
            <p><strong>About the Instructor:</strong> @course.InstructorBio</p>
        </div>
    </div>

    <a href="/courses" class="btn btn-secondary">Back to Course List</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/departments"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>Departments</PageTitle>

<h1>Departments</h1>

<div class="row">
    @foreach (var dept in CatalogService.GetDepartments())
    {
        <div class="col-md-4 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@dept.Code</h6>
                    <p class="card-text">@dept.Description</p>
                    <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-primary">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService
@rendermode InteractiveServer

<PageTitle>Enroll</PageTitle>

<h1>Course Enrollment</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@enrollmentRequest.StudentName</strong>. Your enrollment request has been received.</p>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="enrollmentRequest" OnValidSubmit="HandleSubmit" FormName="enrollForm">
        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="enrollmentRequest.StudentName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="enrollmentRequest.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="enrollmentRequest.CourseId">
                <option value="0">-- Select a Course --</option>
                @foreach (var course in CatalogService.GetCourses(null, null))
                {
                    <option value="@course.Id">@course.Code - @course.Title</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="notes" class="form-label">Notes (optional)</label>
            <InputTextArea id="notes" class="form-control" @bind-Value="enrollmentRequest.Notes" rows="3" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment</button>
    </EditForm>
}

@code {
    private EnrollmentRequest enrollmentRequest = new();
    private bool submitted = false;

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(enrollmentRequest);
        submitted = true;
    }

    private void Reset()
    {
        enrollmentRequest = new();
        submitted = false;
    }
}

